# Helper function to check if a ConditionalStatement has a default case in its chain
has_default(node) {
    node.is_default == true
} else {
    node.else_statement != null
    has_default(node.else_statement)
}

# Check if a ConditionalStatement is a multiple condition expression (SWITCH or multiple branch IF)
