    node.type == "SWITCH"
} else {
    node.type == "IF"
    node.else_statement != null
    node.else_statement.type == "IF"
}

Glitch_Analysis[result] {
    # Get all conditional statements in the current node
    conditions := glitch_lib.all_conditional_statements(input)
    node := conditions[_]
    is_multiple_condition(node)
    not has_default(node)

    result := {
        "type": "sec_no_default_switch",
        "element": node,
        "path": input.path,
        "description": "Missing default case in multiple condition expression (CWE-478)"
    }
