package glitch

import data.glitch_lib

# Helper rule to get all conditions in the chain starting from `c`
chain_helper(c) = conditions {
    conditions := {c}
    c.else_statement != null
    c.else_statement.ir_type == "ConditionalStatement"
    more_conditions := chain_helper(c.else_statement)
    conditions := conditions union more_conditions
} else {
    conditions := {c}
}

# Helper rule to get the last condition in the chain (the one that doesn't have a condition as else_statement)
last_condition_in_chain(top) = last {
    conditions := chain_helper(top)
    # Find the condition in the chain that has an else_statement that is not a condition
    last := [c | 
        c := conditions
        c.else_statement != null
        c.else_statement.ir_type != "ConditionalStatement"
    ][0]
}

# Check if the chain has a default case
has_default_case(top) {
    conditions := chain_helper(top)
    # Check if any condition in the chain is a default (for switch)
    default_conditions := {c | c := conditions; c.is_default == true}
    count(default_conditions) > 0
} else {
    # If no condition is a default, check the last condition for an else block
    last := last_condition_in_chain(top)
    last.else_statement != null
}

# Main rule to detect CWE-478
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Get all conditional statements in the parent
    conditions := glitch_lib.all_conditional_statements(parent)
    # We only want top conditional statements (the start of a chain)
    top_conditions := {c | c := conditions; c.is_top == true}
    top := top_conditions[_]

    # Check if the chain does NOT have a default case
    not has_default_case(top)

    result := {
        "type": "sec_no_default_switch",
        "element": top,
        "path": parent.path,
        "description": "Missing default case in conditional statement - The conditional statement does not have a fallback for unexpected values. (CWE-478)"
    }
}

